import json, hashlib
from sympy import Matrix
from sympy.matrices.normalforms import smith_normal_form
from sympy.polys.domains import ZZ

CASES = [
  {"name":"[222,4^5] in Lambda/I_{5,4}","lower":[2,2,2,0,0],"upper":[4,4,4,4,4],"degrees":list(range(6,21)),"hDegrees":[1,2,3,4]},
  {"name":"[33,5^4] in Lambda/I_{4,5}","lower":[3,3,0,0],"upper":[5,5,5,5],"degrees":list(range(6,21)),"hDegrees":[1,2,3,4,5]}
]

def weight(p): return sum(p)
def contained(a,b): return all(x<=y for x,y in zip(a,b))
def conjugate(p):
    return [sum(x>=c for x in p) for c in range(1,max(p,default=0)+1)]
def horizontal(lam,mu):
    # mu/lam is horizontal iff every conjugate-column increment is 0 or 1.
    L=max(max(lam,default=0),max(mu,default=0))
    cl=conjugate(lam)+[0]*L; cm=conjugate(mu)+[0]*L
    return contained(lam,mu) and all(0 <= cm[c]-cl[c] <= 1 for c in range(L))
def all_partitions(length, maximum):
    def rec(prefix,last,k):
        if k==0:
            yield prefix
        else:
            for x in range(last,-1,-1):
                yield from rec(prefix+[x],x,k-1)
    yield from rec([],maximum,length)
def interval_parts(lower,upper,d):
    ans=[]
    for p in all_partitions(len(upper),upper[0]):
        if weight(p)==d and contained(lower,p) and contained(p,upper): ans.append(p)
    return ans

def compute(case):
    lo,up=case['lower'],case['upper']
    bydeg={d:interval_parts(lo,up,d) for d in case['degrees']}
    out=[]
    for d in case['degrees']:
        cols=bydeg[d]
        labels=[]; rows=[]
        for t in case['hDegrees']:
            srcdeg=d-t
            # Sources outside the requested degree range are empty since |lower|=6.
            srcs=interval_parts(lo,up,srcdeg) if srcdeg>=weight(lo) else []
            for lam in srcs:
                labels.append([t,lam])
                rows.append([1 if horizontal(lam,mu) and weight(mu)-weight(lam)==t else 0 for mu in cols])
        M=Matrix(rows) if rows else Matrix(0,len(cols),[])
        S=smith_normal_form(M,domain=ZZ)
        diag=[abs(int(S[i,i])) for i in range(min(S.rows,S.cols)) if S[i,i] != 0]
        rank=len(diag)
        torsion=[x for x in diag if x>1]
        out.append({"degree":d,"columns":cols,"rowLabels":labels,"M":rows,
                    "shape":[M.rows,M.cols],"smithNonzero":diag,"rank":rank,
                    "quotientFreeRank":len(cols)-rank,"torsionFactors":torsion})
    return {"name":case['name'],"lower":lo,"upper":up,"degrees":case['degrees'],"hDegrees":case['hDegrees'],"degreeData":out}

results=[compute(c) for c in CASES]
comparison=[]
for a,b in zip(results[0]['degreeData'],results[1]['degreeData']):
    comparison.append({"degree":a['degree'],"first":{"freeRank":a['quotientFreeRank'],"torsion":a['torsionFactors']},"second":{"freeRank":b['quotientFreeRank'],"torsion":b['torsionFactors']},"equal":a['quotientFreeRank']==b['quotientFreeRank'] and a['torsionFactors']==b['torsionFactors']})
payload={"input":CASES,"results":results,"comparison":comparison,"allComparedInvariantsEqual":all(x['equal'] for x in comparison)}
text=json.dumps(payload,sort_keys=True,separators=(',',':'))
print(text)
print('STABLE_OUTPUTS_SHA256='+hashlib.sha256(text.encode()).hexdigest())
